import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { logout } from '../redux/slices/authSlice';
import { FaUser, FaWallet, FaSignOutAlt, FaBars, FaTimes } from 'react-icons/fa';

const Header = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [isMenuOpen, setIsMenuOpen] = React.useState(false);
  const { isAuthenticated, userRole, user, captain } = useSelector(
    (state) => state.auth
  );

  const handleLogout = () => {
    dispatch(logout());
    navigate('/');
  };

  const currentUser = user || captain;

  return (
    <header className="bg-white shadow-sm sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          <Link to="/" className="flex items-center gap-2">
            <span className="text-xl font-bold text-blue-600">🚗 Ride Zilla</span>
          </Link>

          {/* Desktop Menu */}
          <nav className="hidden md:flex items-center gap-6">
            {!isAuthenticated ? (
              <>
                <Link to="/login" className="text-gray-600 hover:text-blue-600">
                  Login
                </Link>
                <Link
                  to="/signup"
                  className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700"
                >
                  Sign Up
                </Link>
              </>
            ) : (
              <>
                {userRole === 'user' && (
                  <>
                    <Link to="/rides" className="text-gray-600 hover:text-blue-600">
                      Rides
                    </Link>
                    <Link to="/wallet" className="text-gray-600 hover:text-blue-600">
                      Wallet
                    </Link>
                  </>
                )}
                {userRole === 'captain' && (
                  <>
                    <Link to="/captain-earnings" className="text-gray-600 hover:text-blue-600">
                      Earnings
                    </Link>
                    <Link to="/captain-rides" className="text-gray-600 hover:text-blue-600">
                      Rides
                    </Link>
                  </>
                )}

                <div className="flex items-center gap-4">
                  <Link to="/profile" className="text-gray-600 hover:text-blue-600">
                    <FaUser size={20} />
                  </Link>
                  <button
                    onClick={handleLogout}
                    className="text-gray-600 hover:text-red-600"
                  >
                    <FaSignOutAlt size={20} />
                  </button>
                </div>
              </>
            )}
          </nav>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="md:hidden"
          >
            {isMenuOpen ? (
              <FaTimes size={24} />
            ) : (
              <FaBars size={24} />
            )}
          </button>
        </div>

        {/* Mobile Menu */}
        {isMenuOpen && (
          <nav className="md:hidden pb-4 space-y-3">
            {!isAuthenticated ? (
              <>
                <Link
                  to="/login"
                  className="block text-gray-600 hover:text-blue-600"
                >
                  Login
                </Link>
                <Link
                  to="/signup"
                  className="block bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700"
                >
                  Sign Up
                </Link>
              </>
            ) : (
              <>
                <Link
                  to="/profile"
                  className="block text-gray-600 hover:text-blue-600"
                >
                  Profile
                </Link>
                {userRole === 'user' && (
                  <>
                    <Link
                      to="/rides"
                      className="block text-gray-600 hover:text-blue-600"
                    >
                      My Rides
                    </Link>
                    <Link
                      to="/wallet"
                      className="block text-gray-600 hover:text-blue-600"
                    >
                      Wallet
                    </Link>
                  </>
                )}
                {userRole === 'captain' && (
                  <>
                    <Link
                      to="/captain-earnings"
                      className="block text-gray-600 hover:text-blue-600"
                    >
                      Earnings
                    </Link>
                    <Link
                      to="/captain-rides"
                      className="block text-gray-600 hover:text-blue-600"
                    >
                      My Rides
                    </Link>
                  </>
                )}
                <button
                  onClick={handleLogout}
                  className="block w-full text-left text-red-600 hover:text-red-700"
                >
                  Logout
                </button>
              </>
            )}
          </nav>
        )}
      </div>
    </header>
  );
};

export default Header;
